export const categories={all:'全部餐飲',coffee:'咖啡',dessert:'甜點・飲料',breakfast:'早餐・早午餐',noodles:'麵食',japanese:'日式・咖哩',korean:'韓式',western:'西式・披薩',hotpot:'火鍋',bbq:'燒肉・串燒',asian:'南洋・異國',local:'台式・港式',bar:'餐酒館',veggie:'蔬食',other:'其他餐飲',uncategorized:'待分類'};
export function validPoint(p){return p&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180}
export function distance(a,b){const rad=x=>x*Math.PI/180;const h=Math.sin(rad(b.lat-a.lat)/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(rad(b.lon-a.lon)/2)**2;return 6371*2*Math.asin(Math.sqrt(Math.min(1,Math.max(0,h))))}
export function nearby(places,center,radius,category,lists=[]){if(!validPoint(center)||!(radius>0))return [];const sel=[].concat(category).filter(c=>c&&c!=='all');return places.filter(p=>validPoint(p)&&!p.categories.includes('excluded')&&(sel.length?p.categories.some(c=>sel.includes(c)):!p.categories.includes('uncategorized'))&&(!lists.length||lists.includes(p.list))).map(p=>({...p,distance:distance(center,p)})).filter(p=>p.distance<=radius+1e-9).sort((a,b)=>a.distance-b.distance||a.id.localeCompare(b.id))}
export class Picker{constructor(){this.reset()}reset(){this.bag=[];this.last=null;this.key='';this.round=0}draw(items,random=Math.random){if(!items.length)return null;const key=items.map(x=>x.id).sort().join(',');if(key!==this.key){this.reset();this.key=key}let restarted=false;if(!this.bag.length){restarted=this.round>0;this.round++;this.bag=[...items];for(let i=this.bag.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[this.bag[i],this.bag[j]]=[this.bag[j],this.bag[i]]}if(this.bag.length>1&&this.bag.at(-1).id===this.last){[this.bag[0],this.bag[this.bag.length-1]]=[this.bag.at(-1),this.bag[0]]}}const place=this.bag.pop();this.last=place.id;return {place,restarted,remaining:this.bag.length,round:this.round}}}
export function parseCoordinates(text){const m=text.trim().match(/^(-?\d+(?:\.\d+)?)\s*[,，]\s*(-?\d+(?:\.\d+)?)$/);if(!m)return null;const p={lat:Number(m[1]),lon:Number(m[2])};return validPoint(p)?p:null}
export function normalize(text){return text.normalize('NFKC').toLowerCase().replace(/臺/g,'台').replace(/\s/g,'')}

export function fixAddressQuery(text){return text.normalize('NFKC').replace(/(路|街|大道|段|巷|弄)(\d)/g,'$1 $2').replace(/(\d)號/g,'$1號').trim()}
export function hasCjk(text){return /[\u4e00-\u9fff]/.test(text||'')}
